const UI_FONT_CSS={"Nunito": "@font-face {\n  font-family: 'Nunito';\n  font-style: normal;\n  font-weight: 400;\n  font-display: swap;\n  src: url(data:font/ttf;base64,) format('truetype');\n}@font-face {\n  font-family: 'Nunito';\n  font-style: normal;\n  font-weight: 700;\n  font-display: swap;\n  src: url(data:font/ttf;base64,) format('truetype');\n}", "Roboto": "@font-face {\n  font-family: 'Roboto';\n  font-style: normal;\n  font-weight: 400;\n  font-stretch: normal;\n  font-display: swap;\n  src: url(data:font/ttf;base64,) format('truetype');\n}@font-face {\n  font-family: 'Roboto';\n  font-style: normal;\n  font-weight: 700;\n  font-stretch: normal;\n  font-display: swap;\n  src: url(data:font/ttf;base64,) format('truetype');\n}", "Open Sans": "@font-face {\n  font-family: 'Open Sans';\n  font-style: normal;\n  font-weight: 400;\n  font-stretch: normal;\n  font-display: swap;\n  src: url(data:font/ttf;base64,) format('truetype');\n}@font-face {\n  font-family: 'Open Sans';\n  font-style: normal;\n  font-weight: 700;\n  font-stretch: normal;\n  font-display: swap;\n  src: url(data:font/ttf;base64,) format('truetype');\n}"};
function makeHTML(project){
  const data=JSON.stringify(project).replace(/</g,'\\u003c');
  const fonts=UI_FONT_CSS[project.design.font]||'';
  return '<!doctype html><html lang="'+Loto.esc(project.language||'ru')+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+Loto.esc(project.title)+'</title><style>'+GAME_CSS+MATH_CSS+fonts+'</style></head><body class="standalone"><div class="game-viewport"><main id="game"></main></div><script>'+GAME_SOURCE+'\nconst project='+data+';const game=new LotoGame(document.getElementById("game"),project);LotoViewport.mount(game.root);const scratchKey="scratch:"+project.questions.map(q=>q.id).join("|");game.onScratchChange=data=>LotoStorage.put(scratchKey,data).catch(()=>{});const scratchRevision=game.scratch.revision;LotoStorage.get(scratchKey).then(data=>{if(data&&game.scratch.revision===scratchRevision){game.scratch.restore(data);game.render();}});window.addEventListener("beforeunload",e=>{if(game.session?.status==="playing"&&(game.session.done.size||game.session.errors)){e.preventDefault();e.returnValue="";}});<'+ '/script></body></html>';
}
async function packHTML(html){
  if(typeof CompressionStream==='undefined')return {html,compressed:false};
  const bytes=new Uint8Array(await new Response(new Blob([html]).stream().pipeThrough(new CompressionStream('gzip'))).arrayBuffer());
  let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const payload=btoa(binary);
  const loader='<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#123c33;height:100vh;overflow:hidden"><p id="loading" style="color:white;text-align:center;font:16px Arial;padding:30px">Загрузка игры / Loading…</p><script>(async()=>{try{if(!window.DecompressionStream)throw Error("Используйте современный браузер / Please update your browser");const bytes=Uint8Array.from(atob("'+payload+'"),c=>c.charCodeAt(0));const html=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"))).text();const frame=document.createElement("iframe");frame.title="Learning Lotto";frame.style="display:block;width:100%;height:100dvh;border:0;overflow:hidden";frame.setAttribute("scrolling","no");frame.srcdoc=html;document.body.replaceChildren(frame);}catch(e){document.getElementById("loading").textContent=e.message;}})();<'+ '/script></body></html>';
  return new Blob([loader]).size<new Blob([html]).size?{html:loader,compressed:true}:{html,compressed:false};
}
